export fn longest_increasing_subsequence_iterative(v:[*]const i64,n:usize)i64{if(n<1 or n>65)return -1;const count=v[0];if(count<0 or count>64 or n!=@as(usize,@intCast(count))+1)return -1;var dp:[64]i64=@splat(1);for(0..@as(usize,@intCast(count)))|i|{if(v[i+1]< -1000000 or v[i+1]>1000000)return -1;}for(0..@as(usize,@intCast(count)))|i|{for(0..i)|j|{if(v[j+1]<=v[i+1] and dp[j]+1>dp[i])dp[i]=dp[j]+1;}}var best:i64=0;for(0..@as(usize,@intCast(count)))|i|{if(dp[i]>best)best=dp[i];}return best;}
